use std::fs
use std::process

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut w: int = 0
    let mut cur = ""
    let mut curlen: int = 0
    for line in text.lines() {
        if first {
            first = false
            let r = line.trim().parse::<int>()
            match r {
                Ok(v) => { w = v }
                Err(_) => { w = 0 }
            }
            if w <= 0 {
                println("error: bad width")
                process::exit(1)
            }
        } else {
            for word in line.split_whitespace() {
                let n: int = word.len() as int
                if curlen == 0 {
                    cur = word
                    curlen = n
                } else if curlen + 1 + n <= w {
                    cur = "${cur} ${word}"
                    curlen = curlen + 1 + n
                } else {
                    println(cur)
                    cur = word
                    curlen = n
                }
            }
        }
    }
    if first {
        println("error: bad width")
        process::exit(1)
    }
    if curlen > 0 {
        println(cur)
    }
}

